import{_ as i,c as a,o as s,j as o,Y as n,t as r}from"./chunks/framework.D-NV0Bun.js";const k=JSON.parse('{"title":"git-contacts | x-cmd man (git man1) | List people who might be interested in a set of changes","titleTemplate":false,"description":"x-cmd man (git man1 Manual Page) | git-contacts - List people who might be interested in a set of changes","frontmatter":{"pageClass":"x-man","head":[["meta",{"name":"og:title","content":"git-contacts | x-cmd man (git man1) | List people who might be interested in a set of changes"}],["meta",{"name":"og:description","content":"x-cmd man (git man1 Manual Page) | git-contacts - List people who might be interested in a set of changes"}]]},"headers":[],"params":{"isMan":true,"man":"git-contacts","category":"git man1","desc":"List people who might be interested in a set of changes"},"relativePath":"git/man1/git-contacts.md","filePath":"git/man1/[man].md"}'),c={name:"git/man1/git-contacts.md"},h={class:"visually-hidden"};function l(t,e,p,d,g,m){return s(),a("div",null,[o("h1",h,r(t.$params.man),1),e[0]||(e[0]=n(`<h2 id="name" tabindex="-1">NAME <a class="header-anchor" href="#name" aria-label="Permalink to &quot;NAME&quot;">​</a></h2><p>git-contacts - List people who might be interested in a set of changes</p><h2 id="synopsis" tabindex="-1">SYNOPSIS <a class="header-anchor" href="#synopsis" aria-label="Permalink to &quot;SYNOPSIS&quot;">​</a></h2><div class="language-sh vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">sh</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">git</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> contacts</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> (&lt;patch&gt;</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">|&lt;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">range</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">&gt;|&lt;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">rev</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">&gt;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">)...</span></span></code></pre></div><h2 id="description" tabindex="-1">DESCRIPTION <a class="header-anchor" href="#description" aria-label="Permalink to &quot;DESCRIPTION&quot;">​</a></h2><p>Given a set of changes, specified as patch files or revisions, determine people who might be interested in those changes. This is done by consulting the history of each patch or revision hunk to find people mentioned by commits which touched the lines of files under consideration.</p><p>Input consists of one or more patch files or revision arguments. A revision argument can be a range or a single <strong>&lt;rev&gt;</strong> which is interpreted as <strong>&lt;rev&gt;..HEAD</strong>, thus the same revision arguments are accepted as for <strong>git-format-patch</strong>(1). Patch files and revision arguments can be combined in the same invocation.</p><p>This command can be useful for determining the list of people with whom to discuss proposed changes, or for finding the list of recipients to Cc: when submitting a patch series via <strong>git send-email</strong>. For the latter case, <strong>git contacts</strong> can be used as the argument to <strong>git send-email</strong>&#39;s <strong>--cc-cmd</strong> option.</p><h2 id="discussion" tabindex="-1">DISCUSSION <a class="header-anchor" href="#discussion" aria-label="Permalink to &quot;DISCUSSION&quot;">​</a></h2><p><strong>git blame</strong> is invoked for each hunk in a patch file or revision. For each commit mentioned by <strong>git blame</strong>, the commit message is consulted for people who authored, reviewed, signed, acknowledged, or were Cc:&#39;d. Once the list of participants is known, each person&#39;s relevance is computed by considering how many commits mentioned that person compared with the total number of commits under consideration. The final output consists only of participants who exceed a minimum threshold of participation.</p><h2 id="output" tabindex="-1">OUTPUT <a class="header-anchor" href="#output" aria-label="Permalink to &quot;OUTPUT&quot;">​</a></h2><p>For each person of interest, a single line is output, terminated by a newline. If the person&#39;s name is known, &quot;Name &lt;user@host&gt;&quot; is printed; otherwise only &quot;&lt;user@host&gt;&quot; is printed.</p><h2 id="examples" tabindex="-1">EXAMPLES <a class="header-anchor" href="#examples" aria-label="Permalink to &quot;EXAMPLES&quot;">​</a></h2><blockquote><p>·</p><p>Consult patch files:</p><blockquote><pre><code>$ git contacts feature/*.patch
</code></pre></blockquote></blockquote><blockquote><p>·</p><p>Revision range:</p><blockquote><pre><code>$ git contacts R1..R2
</code></pre></blockquote></blockquote><blockquote><p>·</p><p>From a single revision to <strong>HEAD</strong>:</p><blockquote><pre><code>$ git contacts origin
</code></pre></blockquote></blockquote><blockquote><p>·</p><p>Helper for <strong>git send-email</strong>:</p><blockquote><pre><code>$ git send-email --cc-cmd=&#39;git contacts&#39; feature/*.patch
</code></pre></blockquote></blockquote><h2 id="limitations" tabindex="-1">LIMITATIONS <a class="header-anchor" href="#limitations" aria-label="Permalink to &quot;LIMITATIONS&quot;">​</a></h2><p>Several conditions controlling a person&#39;s significance are currently hard-coded, such as minimum participation level (10%), blame date-limiting (5 years), and <strong>-C</strong> level for detecting moved and copied lines (a single <strong>-C</strong>). In the future, these conditions may become configurable.</p><h2 id="git" tabindex="-1">GIT <a class="header-anchor" href="#git" aria-label="Permalink to &quot;GIT&quot;">​</a></h2><p>Part of the <strong>git</strong>(1) suite</p>`,21))])}const b=i(c,[["render",l]]);export{k as __pageData,b as default};
